package com.arnavgames.tycoon.core.content

import kotlinx.serialization.Serializable

/**
 * World, rivals and finance pressure (content/data/world.json, generated by tools/content/gen_world.py).
 * docs/GDD.md §9–11, docs/ECONOMY.md §8.
 */
@Serializable
data class WorldContent(
    val archetypes: List<ArchetypeDef>,
    val rivals: List<RivalDef>,
    val nemeses: List<NemesisDef>,
    val events: List<WorldEventDef>,
    val cards: List<CardDef>,
    val config: WorldConfig,
) {
    @kotlinx.serialization.Transient val rivalById: Map<String, RivalDef> = rivals.associateBy { it.id }
    @kotlinx.serialization.Transient val cardById: Map<String, CardDef> = cards.associateBy { it.id }
    @kotlinx.serialization.Transient val eventById: Map<String, WorldEventDef> = events.associateBy { it.id }
    @kotlinx.serialization.Transient val archetypeById: Map<String, ArchetypeDef> = archetypes.associateBy { it.id }
    @kotlinx.serialization.Transient val nemesisByChapter: Map<Int, NemesisDef> = nemeses.associateBy { it.chapter }

    companion object {
        val EMPTY = WorldContent(emptyList(), emptyList(), emptyList(), emptyList(), emptyList(), WorldConfig())
    }
}

@Serializable
data class ArchetypeDef(val id: String, val name: String, val description: String)

/**
 * A rival billionaire. Net worth is a pure function of time:
 * `log10(NW) = base + growth · G(days) + wobble · sin(2π · days / periodDays + phase(worldSeed, id))`, where G is the
 * reference curve (WorldConfig.rivalCurve) and days are game days since the current generation began.
 */
@Serializable
data class RivalDef(
    val id: String,
    val name: String,
    val archetype: String,
    val city: String,
    val sectors: List<String>,
    /** How the fortune was made (flavour text). */
    val source: String,
    val age: Int,
    val aggression: Double,
    val risk: Double,
    val base: Double,
    val growth: Double,
    val wobble: Double,
    val periodDays: Double,
    /** A bundled caricature portrait exists (img/rivals/<id>.webp); otherwise the UI draws a monogram. */
    val portrait: Boolean = false,
)

/** A chapter's nemesis and three story beats: intro (chapter start), midpoint (half the missions), finale (chapter done). */
@Serializable
data class NemesisDef(val chapter: Int, val rival: String, val beats: List<String>)

/**
 * A world event. scope "sector" (target = market sector id), "all", or "city" (a disaster: target = estates city id,
 * uninsured properties there lose condition). pct is the business income change while active.
 */
@Serializable
data class WorldEventDef(
    val id: String,
    val title: String,
    val text: String,
    val scope: String,
    val target: String = "",
    val pct: Double = 0.0,
    val hours: Int = 0,
    /** Draw weight by macro phase id. */
    val weights: Map<String, Double> = emptyMap(),
)

/**
 * A decision card (GDD §9). kind: business, world, personal, acquisition, jv, takeover, rival or nemesis.
 * requires: "none", "biz:any" or "biz:<businessId>". Text placeholders: {business}, {rival}.
 */
@Serializable
data class CardDef(
    val id: String,
    val kind: String,
    val chapter: Int,
    val requires: String,
    val title: String,
    val text: String,
    val options: List<CardOptionDef>,
    val weight: Double = 1.0,
)

@Serializable
data class CardOptionDef(
    val label: String,
    val detail: String = "",
    val outcomes: List<CardOutcomeDef>,
    /** "ally": only available when some rival's relationship with you is at least the ally threshold. */
    val requires: String? = null,
)

@Serializable
data class CardOutcomeDef(val p: Double, val text: String = "", val effects: List<CardEffectDef> = emptyList())

/**
 * One effect. Amounts in `hours` are hours of the player's total business income at the moment of choosing.
 * type: cash (hours ±), income (target business|all|sector, pct, hours), credit (points), relation (points),
 * donation (hours; cash cost and a tax deduction), rd (hours; cash cost and an R&D credit), sell (multiple × valuation).
 */
@Serializable
data class CardEffectDef(
    val type: String,
    val hours: Double = 0.0,
    val target: String = "",
    val pct: Double = 0.0,
    val points: Int = 0,
    val multiple: Double = 0.0,
)

@Serializable
data class WorldConfig(
    val unlocks: Map<String, Int> = emptyMap(),
    val cards: CardsConfig = CardsConfig(),
    val events: EventsConfig = EventsConfig(),
    val finance: FinanceConfig = FinanceConfig(),
    val rivalCurve: RivalCurveConfig = RivalCurveConfig(),
)

/** Reference growth of rival fortunes in log10 per game day: fast until the knee, slower after. */
@Serializable
data class RivalCurveConfig(val earlyPerDay: Double = 1.4, val kneeDays: Double = 4.5, val latePerDay: Double = 0.4)

@Serializable
data class CardsConfig(
    val firstAtMinutes: Int = 30,
    val everyHours: Double = 4.0,
    val jitterMin: Double = 0.75,
    val jitterMax: Double = 1.5,
    val maxQueued: Int = 3,
    /** Card ids drawn within this many draws are not drawn again. */
    val recentWindow: Int = 24,
    /** Income penalty on a business while a takeover card against it is pending. */
    val takeoverPenalty: Double = 0.10,
    /** Relationship needed for a rival to act as your white knight. */
    val allyRelation: Int = 40,
)

@Serializable
data class EventsConfig(
    val firstAfterHours: Double = 6.0,
    val everyHoursMin: Double = 16.0,
    val everyHoursMax: Double = 30.0,
    val maxActive: Int = 3,
    val disasterDamageMin: Int = 250,
    val disasterDamageMax: Int = 500,
)

@Serializable
data class RatingDef(val name: String, val min: Int, val spreadPerDay: Double, val borrowFactor: Double, val maxLtv: Double)

@Serializable
data class DtiStep(val days: Double, val points: Int)

@Serializable
data class TaxBracketDef(val upToPerHour: Dollars? = null, val rate: Double)

@Serializable
data class DeductionsConfig(
    val rd: Double = 0.03,
    val rdPoolCap: Double = 0.03,
    val depreciationPerProperty: Double = 0.01,
    val depreciationMax: Double = 0.04,
    val green: Double = 0.03,
    val donationCap: Double = 0.05,
    val max: Double = 0.12,
)

@Serializable
data class FinanceConfig(
    val scoreStart: Int = 700,
    val scoreMin: Int = 300,
    val scoreMax: Int = 850,
    val onTimePoints: Int = 3,
    val missedPoints: Int = -25,
    val foreclosurePoints: Int = -60,
    val auditPoints: Int = -40,
    val restructurePoints: Int = -40,
    val recoverTo: Int = 680,
    val recoverPer6h: Int = 1,
    val phoenixScore: Int = 600,
    val dti: List<DtiStep> = emptyList(),
    val ratings: List<RatingDef> = emptyList(),
    val loanTermsDays: List<Int> = listOf(1, 3, 7),
    val borrowIncomeHours: Double = 24.0,
    val borrowNetWorthShare: Double = 0.4,
    val creditLineIncomeHours: Double = 12.0,
    val missedPenalty: Double = 0.02,
    val taxBrackets: List<TaxBracketDef> = emptyList(),
    val quarterHours: Int = 72,
    val filingWindowHours: Int = 24,
    val deductions: DeductionsConfig = DeductionsConfig(),
    val rdBusinesses: List<String> = emptyList(),
    val greenBusinesses: List<String> = emptyList(),
    val aggressiveExtraMin: Double = 0.05,
    val aggressiveExtraMax: Double = 0.10,
    val auditChanceMin: Double = 0.15,
    val auditChanceMax: Double = 0.35,
    val auditPenaltyMultiple: Double = 2.0,
    val phoenixNegativeMinutes: Int = 30,
    val phoenixKeepLevels: Double = 0.1,
    val phoenixBoost: Double = 3.0,
    val phoenixBoostHours: Int = 2,
)
